    - Skeleton loading cards (not just a spinner)
    - Better error messages with title + detail
    - Smooth hero → compact transition on first search
    - Stack pills in footer
    - All state and logic explained inline
*/

import React, { useState, useEffect } from 'react';
import PaperCard from './components/PaperCard';
import { searchPapers, checkHealth } from './services/api';
import './App.css';

/* ── Skeleton card component ────────────────────────────────── */
/*
  Skeleton screens show placeholder shapes while data loads.
  Much better UX than a blank screen or just a spinner:
  - Users can see how many results are coming
  - The page doesn't "jump" when content appears
  - The shimmer animation signals active loading
*/
function SkeletonCard() {
  return (
    <div className="skeleton-card">
      <div className="skeleton-line sk-title"></div>
      <div className="skeleton-line sk-meta"></div>
      <div className="skeleton-line sk-body"></div>
      <div className="skeleton-line sk-body"></div>
      <div className="skeleton-line sk-body"></div>
    </div>
  );
}

/* ── Main App component ─────────────────────────────────────── */
function App() {

  // ── State ──────────────────────────────────────────────────
  const [query, setQuery]           = useState('');
  // Current text in the search input

  const [source, setSource]         = useState('arxiv');
  // Which API source: 'arxiv' | 'semantic_scholar' | 'auto'

  const [summarize, setSummarize]   = useState(true);
  // Toggle AI summaries on/off per search

  const [papers, setPapers]         = useState([]);
  // Array of paper objects from the API

  const [loading, setLoading]       = useState(false);
  // True while fetching — shows skeleton + disables input

  const [error, setError]           = useState(null);
  // null = no error | { title, detail } = error to display

  const [lastQuery, setLastQuery]   = useState('');
  const [sourceUsed, setSourceUsed] = useState('');
  const [summariesOn, setSummariesOn] = useState(false);
  const [total, setTotal]           = useState(0);
  const [hasSearched, setHasSearched] = useState(false);
  // Tracks if ANY search has happened — controls hero visibility

  const [backendStatus, setBackendStatus] = useState(null);
  // Health check result from /api/papers/health

  // ── Effects ────────────────────────────────────────────────
  useEffect(() => {
    /*
      Health check on mount ([] = run once).
      We check silently — doesn't block the UI.
      Just updates the status dot in the header.
    */
    checkHealth()
      .then(h => setBackendStatus(h))
      .catch(() => setBackendStatus({ status: 'offline' }));
  }, []);

  // ── Search handler ─────────────────────────────────────────
  const handleSearch = async (q, src, sum) => {
    const trimmed = (q || query).trim();
    if (trimmed.length < 2) return;

    setLoading(true);
    setError(null);
    setHasSearched(true);

    try {
      const data = await searchPapers(trimmed, 10, src || source, sum ?? summarize);
      setPapers(data.papers || []);
      setTotal(data.total || 0);
      setSourceUsed(data.source_used || src || source);
      setSummariesOn(data.summaries_enabled || false);
      setLastQuery(trimmed);

    } catch (err) {
      /*
        We give the user TWO pieces of error info:
          title  → short, friendly summary
          detail → technical detail (for debugging)

        This is better than showing raw error strings.
      */
      console.error('Search failed:', err);

      if (!err.response) {
        setError({
          title: 'Cannot connect to backend',
          detail: 'Make sure FastAPI is running: uvicorn app.main:app --reload',
        });
      } else if (err.response.status === 503) {
        setError({
          title: 'API service unavailable',
          detail: err.response.data?.detail || 'Try switching to arXiv source.',
        });
      } else {
        setError({
          title: 'Search failed',
          detail: err.response?.data?.detail || err.message,
        });
      }
      setPapers([]);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    handleSearch(query, source, summarize);
  };

  // ── Render ─────────────────────────────────────────────────
  return (
    <div className="app">

      {/* Atmospheric background */}
      <div className="bg-ambient" aria-hidden="true">
        <div className="ambient-blob blob-gold-tr"></div>
        <div className="ambient-blob blob-teal-bl"></div>
        <div className="ambient-blob blob-gold-tc"></div>
      </div>

      {/* ── Header ── */}
      <header className="app-header">
        <div className="header-inner">
          <div className="brand">
            <div className="brand-mark" aria-hidden="true">⚗</div>
            <div>
              <div className="brand-name">Research Finder</div>
              <div className="brand-tagline">AI-powered paper discovery</div>
            </div>
          </div>

          {backendStatus && (
            <div className={`status-pill ${backendStatus.status === 'ok' ? 'online' : 'offline'}`}>
              <span className="status-dot"></span>
              {backendStatus.status === 'ok' ? 'Backend online' : 'Backend offline'}
            </div>
          )}
        </div>
      </header>

      {/* ── Main ── */}
      <main className="app-main">

        {/* Hero — only shown before first search */}
        {!hasSearched && (
          <section className="hero">
            <div className="hero-eyebrow">
              <span className="eyebrow-dot"></span>
              AI-Powered Research Discovery
            </div>
            <h1 className="hero-heading">
              Find the papers<br />
              that <em>matter most</em>
            </h1>
            <p className="hero-sub">
              Search millions of academic papers from arXiv and Semantic Scholar.
              Get AI-generated summaries so you understand each paper at a glance.
            </p>
            <div className="chip-row">
              <span className="chip-label">Try:</span>
              {[
                'medical image segmentation',
                'large language models',
                'quantum computing',
                'climate change AI',
              ].map(ex => (
                <button
                  key={ex}
                  className="chip"
                  onClick={() => {
                    setQuery(ex);
                    handleSearch(ex, source, summarize);
                  }}
                >
                  {ex}
                </button>
              ))}
            </div>
          </section>
        )}

        {/* ── Search form ── */}
        <section className="search-section">
          <form onSubmit={handleSubmit}>
            <div className="search-box">
              <span className="search-icon" aria-hidden="true">🔍</span>
              <input
                type="text"
                className="search-input"
                placeholder="e.g. transformer neural networks, medical imaging..."
                value={query}
                onChange={e => setQuery(e.target.value)}
                disabled={loading}
                aria-label="Search research papers"
              />
              <button
                type="submit"
                className="search-btn"
                disabled={loading || query.trim().length < 2}
              >
                {loading
                  ? <span className="btn-spinner"></span>
                  : '🔍 Search'
                }
              </button>
            </div>

            {/* Options bar */}
            <div className="search-options">
              <div className="opt-group">
                <label className="opt-label" htmlFor="source-select">Source</label>
                {/*
                  htmlFor links the label to the input by ID.
                  Clicking the label focuses the select — better accessibility.
                  Same as wrapping in a <label> tag.
                */}
                <select
                  id="source-select"
                  className="opt-select"
                  value={source}
                  onChange={e => setSource(e.target.value)}
                  disabled={loading}
                >
                  <option value="arxiv">arXiv (free, always works)</option>
                  <option value="semantic_scholar">Semantic Scholar (API key needed)</option>
                  <option value="auto">Auto (tries both)</option>
                </select>
              </div>

              <div className="opt-group toggle-wrap">
                <span className="opt-label">AI Summaries</span>
                <label className="toggle" aria-label="Toggle AI summaries">
                  <input
                    type="checkbox"
                    checked={summarize}
                    onChange={e => setSummarize(e.target.checked)}
                    disabled={loading}
                  />
                  <span className="toggle-track"></span>
                  <span className="toggle-thumb"></span>
                </label>
              </div>
            </div>
          </form>
        </section>

        {/* ── Error ── */}
        {error && (
          <div className="error-bar" role="alert">
            {/* role="alert" tells screen readers to announce this immediately */}
            <span className="error-icon" aria-hidden="true">⚠️</span>
            <div className="error-body">
              <div className="error-title">{error.title}</div>
              <div className="error-detail">{error.detail}</div>
            </div>
            <button
              className="error-close"
              onClick={() => setError(null)}
              aria-label="Dismiss error"
            >
              ✕
            </button>
          </div>
        )}

        {/* ── Loading skeleton ── */}
        {loading && (
          <div className="loading-view">
            <div className="loader-ring"></div>
            <p className="loader-text">Searching papers…</p>
            <p className="loader-sub">Fetching and summarizing results</p>
            <div className="skeleton-list" style={{ marginTop: 32 }}>
              {[0,1,2].map(i => <SkeletonCard key={i} />)}
              {/*
                We show 3 skeleton cards — the typical number users see
                before the real results load. Matches the expected layout.
              */}
            </div>
          </div>
        )}

        {/* ── Results ── */}
        {!loading && hasSearched && (
          <section className="results-section">

            {papers.length === 0 ? (
              <div className="empty-state">
                <div className="empty-icon" aria-hidden="true">🔎</div>
                <h2 className="empty-title">No papers found for "{lastQuery}"</h2>
                <p className="empty-sub">Try different keywords or switch to a different source.</p>
              </div>
            ) : (
              <>
                {/* Results metadata bar */}
                <div className="results-bar">
                  <p className="results-count">
                    <strong>{total}</strong> papers for{' '}
                    <span className="results-query">"{lastQuery}"</span>
                  </p>
                  <div className="results-tags">
                    <span className="tag tag-source">📡 {sourceUsed}</span>
                    {summariesOn && (
                      <span className="tag tag-summary">🤖 AI summaries</span>
                    )}
                  </div>
                </div>

                {/* Paper cards */}
                <div className="papers-list">
                  {papers.map((paper, i) => (
                    <PaperCard
                      key={`${paper.title}-${paper.year}-${i}`}
                      paper={paper}
                      index={i}
                    />
                  ))}
                </div>
              </>
            )}
          </section>
        )}

      </main>

      {/* ── Footer ── */}
      <footer className="app-footer">
        <div className="footer-inner">
          <p className="footer-copy">© 2026 Research Finder · Built for learning</p>
          <div className="footer-stack">
            {['React', 'FastAPI', 'arXiv', 'Semantic Scholar', 'BART'].map(t => (
              <span key={t} className="stack-pill">{t}</span>
            ))}
          </div>
        </div>
      </footer>

    </div>
  );
}

export default App;
